import {mountThemePicker} from './theme.js';

const $=selector=>document.querySelector(selector);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const number=value=>Number.isFinite(Number(value))?Math.max(0,Number(value)):0;
const count=value=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(number(value));
const compact=value=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(number(value));
const lists=(value,max=500)=>Array.isArray(value)?value.slice(0,max):[];
const query=new URLSearchParams(location.search),demo=query.get('demo')==='1';
const rangeSelect=$('#dashboard-range'),fetchState=$('#fetch-state'),content=$('#dashboard-content');
const allowedTabs=['overview','content','campaigns','inbox'];
let tab=allowedTabs.includes(location.hash.slice(1))?location.hash.slice(1):'overview';
let snapshot=null,request=null,generation=0,disposed=false,chartIndex=-1,toastTimer=0;
const pendingInquiries=new Set();
const cleanups=[];
function listen(target,event,callback,options){target.addEventListener(event,callback,options);cleanups.push(()=>target.removeEventListener(event,callback,options))}
function toast(message){const node=$('#dash-toast');clearTimeout(toastTimer);node.textContent=message;node.hidden=false;toastTimer=setTimeout(()=>node.hidden=true,3500)}
const removeThemePicker=mountThemePicker($('#dashboard-theme'));cleanups.push(removeThemePicker);
const demoLink=$('#demo-mode-toggle');demoLink.href=demo?'dashboard.html':'dashboard.html?demo=1';demoLink.innerHTML=demo?'Recorded data <span aria-hidden="true">↗</span>':'Demo workspace <span aria-hidden="true">↗</span>';

function normalize(payload){
  const metrics={};for(const key of ['views','visitors','engagedSessions','resumeDownloads','filmPlays','inquiries'])metrics[key]=number(payload.totals?.[key]);
  return{...payload,totals:metrics,
    series:lists(payload.series,366).filter(row=>row&&typeof row.date==='string'&&!Number.isNaN(new Date(row.date).getTime())).map(row=>({date:row.date,views:number(row.views),visitors:number(row.visitors)})).sort((a,b)=>a.date.localeCompare(b.date)),
    pages:lists(payload.pages).filter(Boolean).map(row=>({path:String(row.path||'/').slice(0,2000),views:number(row.views),engaged:number(row.engaged)})),
    referrers:lists(payload.referrers).filter(Boolean).map(row=>({source:String(row.source||'Direct / unknown').slice(0,1000),views:number(row.views)})).sort((a,b)=>b.views-a.views),
    campaigns:lists(payload.campaigns).filter(Boolean).map(row=>({source:String(row.source||'—').slice(0,200),medium:String(row.medium||'—').slice(0,200),campaign:String(row.campaign||'(unlabeled)').slice(0,500),views:number(row.views),conversions:number(row.conversions)})),
    events:lists(payload.events).filter(Boolean).map(row=>({name:String(row.name||'event').slice(0,200),count:number(row.count)})).sort((a,b)=>b.count-a.count),
    inquiries:lists(payload.inquiries).filter(Boolean).map(row=>({id:String(row.id),name:String(row.name||'No name supplied').slice(0,200),email:String(row.email||'').slice(0,500),message:String(row.message||'').slice(0,20000),createdAt:String(row.createdAt||row.created_at||''),status:['new','reviewed','archived'].includes(row.status)?row.status:'new'}))
  };
}
function dateLabel(value,long=false){const date=new Date(value);return Number.isNaN(date.getTime())?'Date unavailable':date.toLocaleDateString('en-US',{month:long?'long':'short',day:'numeric',...(long?{year:'numeric'}:{}) ,timeZone:String(value).includes('T')?'America/Chicago':'UTC'})}
function delta(key){const previous=snapshot?.previous?.totals||snapshot?.previous;if(!previous||!Object.hasOwn(previous,key))return'<span>Previous period unavailable</span>';const current=snapshot.totals[key],before=number(previous[key]);if(current===before)return'<span>No change from previous period</span>';if(before===0)return`<b data-direction="up">+${count(current)}</b><span>vs previous period</span>`;const change=(current-before)/before*100;return`<b data-direction="${change<0?'down':'up'}">${change<0?'−':'+'}${Math.abs(change).toFixed(1)}%</b><span>vs previous period</span>`}
function renderKPIs(){const cards=[['views','PAGE VIEWS','↗','Recorded page-view events'],['visitors','ANONYMOUS SESSIONS','◈','Anonymous sessions, not identified people'],['engagedSessions','ENGAGED SESSIONS','✳','Sessions with a recorded engagement event'],['inquiries','INQUIRIES','↗','Messages received by the portfolio form']];$('#dashboard-kpis').innerHTML=cards.map(([key,label,icon,description])=>`<article class="dash-kpi" title="${description}"><p>${label}<span aria-hidden="true">${icon}</span></p><strong>${count(snapshot.totals[key])}</strong><small>${delta(key)}</small></article>`).join('');$('#action-metrics').innerHTML=`<div><span>FILM PLAYS</span><strong>${count(snapshot.totals.filmPlays)}</strong></div><div><span>RÉSUMÉ DOWNLOADS</span><strong>${count(snapshot.totals.resumeDownloads)}</strong></div>`;$('#nav-inbox-count').textContent=count(snapshot.inquiries.filter(row=>row.status==='new').length)}
function emptyTable(columns,title,detail=''){return`<tr><td class="dash-table-empty" colspan="${columns}">${escapeHTML(title)}${detail?`<small>${escapeHTML(detail)}</small>`:''}</td></tr>`}
function pageRows(rows,limit=Infinity){const max=Math.max(1,...rows.map(row=>row.views));return rows.slice(0,limit).map((row,index)=>`<tr><td><div class="dash-path"><span class="dash-path-index">${String(index+1).padStart(2,'0')}</span><div style="min-width:0;flex:1"><span class="dash-path-label" title="${escapeHTML(row.path)}">${escapeHTML(row.path)}</span><span class="dash-page-bar"><span style="width:${Math.max(0,Math.min(100,row.views/max*100)).toFixed(2)}%"></span></span></div></div></td><td>${count(row.views)}</td><td>${count(row.engaged)}</td></tr>`).join('')}
function pagesTable(rows,limit=Infinity,filtered=false){return`<table class="dash-table"><thead><tr><th scope="col">Page path</th><th scope="col">Views</th><th scope="col">Engaged</th></tr></thead><tbody>${rows.length?pageRows(rows,limit):emptyTable(3,filtered?'No page paths match this filter.':'No page activity in this period.',filtered?'Try a shorter path or clear the search.':'Recorded visits will populate this table.')}</tbody></table>`}
function filteredPages(){if(!snapshot)return[];const query=$('#content-search').value.trim().toLowerCase(),sort=$('#content-sort').value;return snapshot.pages.filter(row=>row.path.toLowerCase().includes(query)).sort((a,b)=>sort==='path'?a.path.localeCompare(b.path):sort==='engaged'?b.engaged-a.engaged||b.views-a.views:b.views-a.views||a.path.localeCompare(b.path))}
function renderPages(){const ordered=snapshot.pages.slice().sort((a,b)=>b.views-a.views);$('#top-pages').innerHTML=pagesTable(ordered,5);const filtered=filteredPages();$('#content-table').innerHTML=pagesTable(filtered,Infinity,Boolean($('#content-search').value.trim())&&snapshot.pages.length>0);$('#content-result-count').textContent=`${count(filtered.length)} recorded ${filtered.length===1?'page':'pages'}`}
function renderChannels(){const total=snapshot.referrers.reduce((sum,row)=>sum+row.views,0);$('#traffic-channels').innerHTML=snapshot.referrers.length?snapshot.referrers.slice(0,6).map(row=>`<div class="dash-channel"><div class="dash-channel-row"><span class="dash-channel-name" title="${escapeHTML(row.source)}">${escapeHTML(row.source)}</span><strong>${count(row.views)} <span aria-hidden="true">/</span> ${total?(row.views/total*100).toFixed(0):0}%</strong></div><div class="dash-channel-track"><span style="width:${total?Math.max(0,Math.min(100,row.views/total*100)).toFixed(2):0}%"></span></div></div>`).join(''):'<p class="dash-empty-small">No recorded referral traffic yet.<br>The first arrival will appear here.</p>';$('#event-list').innerHTML=snapshot.events.length?snapshot.events.slice(0,5).map(row=>`<div class="dash-event-row"><span title="${escapeHTML(row.name)}">${escapeHTML(row.name.replace(/[_-]/g,' '))}</span><strong>${count(row.count)}</strong></div>`).join(''):'<p class="dash-empty-small">Recorded interactions will appear here.</p>'}
function renderCampaigns(){$('#campaign-table').innerHTML=`<table class="dash-table"><thead><tr><th scope="col">Campaign / origin</th><th scope="col">Views</th><th scope="col">Conversions</th></tr></thead><tbody>${snapshot.campaigns.length?snapshot.campaigns.slice().sort((a,b)=>b.views-a.views).map(row=>`<tr><td class="dash-campaign-label"><strong>${escapeHTML(row.campaign)}</strong><small>${escapeHTML(row.source)} / ${escapeHTML(row.medium)}</small></td><td>${count(row.views)}</td><td>${count(row.conversions)}</td></tr>`).join(''):emptyTable(3,'No tagged traffic yet.','Build a campaign link, then use it when sharing your work.')}</tbody></table>`}
function filteredInquiries(){if(!snapshot)return[];const filter=$('#inbox-filter').value;return snapshot.inquiries.filter(row=>filter==='all'||row.status===filter).sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime())}
function renderInbox(){const messages=filteredInquiries();$('#inbox-result-count').textContent=`${count(messages.length)} ${messages.length===1?'message':'messages'} in this view. Status changes stay in this workspace; no reply is sent.`;$('#inbox-list').innerHTML=messages.length?messages.map(row=>{const actions=row.status==='new'?[['reviewed','Mark reviewed'],['archived','Archive']]:row.status==='reviewed'?[['new','Mark new'],['archived','Archive']]:[['new','Restore as new'],['reviewed','Mark reviewed']];return`<article class="dash-message" data-message-id="${escapeHTML(row.id)}"><header class="dash-message-header"><div class="dash-message-person"><span class="dash-message-initial" aria-hidden="true">${escapeHTML(row.name.slice(0,1).toUpperCase())}</span><div><h3>${escapeHTML(row.name)}</h3><p>${escapeHTML(row.email)}</p></div></div><time class="dash-message-time"${Number.isNaN(new Date(row.createdAt).getTime())?'':` datetime="${escapeHTML(row.createdAt)}"`}>${escapeHTML(dateLabel(row.createdAt,true))}</time></header><p class="dash-message-body">${escapeHTML(row.message)}</p><footer class="dash-message-footer"><div class="dash-message-status-row"><span class="dash-message-status" data-status="${row.status}">${row.status}</span></div><div class="dash-message-actions">${actions.map(([status,label])=>`<button type="button" data-inquiry-id="${escapeHTML(row.id)}" data-inquiry-status="${status}"${demo||pendingInquiries.has(row.id)?' disabled':''}>${label}</button>`).join('')}</div></footer></article>`}).join(''):`<div class="dash-inbox-empty"><span aria-hidden="true">⊡</span><h3>${snapshot.inquiries.length?'No messages in this view.':'An open line. A quiet inbox.'}</h3><p>${snapshot.inquiries.length?'Choose another status to see the rest.':'Messages submitted through the site will appear here.'}</p></div>`}
function renderMode(){const badge=$('#data-mode'),note=$('#data-note');badge.dataset.mode=snapshot.mode||'unknown';badge.replaceChildren();const dot=document.createElement('i');badge.append(dot,document.createTextNode(snapshot.mode==='demo'?'DEMO WORKSPACE':snapshot.mode==='local'?'LOCAL DATABASE':snapshot.mode==='production'?'PRODUCTION DATA':'DATA CONNECTED'));if(snapshot.mode==='demo'){note.hidden=false;note.innerHTML='<strong>Demonstration workspace.</strong> All figures and messages below are synthetic sample data. They are separate from collected traffic; inbox changes are disabled.'}else if(snapshot.mode==='local'){note.hidden=false;note.innerHTML='<strong>Local database.</strong> These figures come from activity recorded by this development site. They do not represent production visitors. Anonymous sessions are not identified people.'}else{note.hidden=false;note.innerHTML='<strong>Recorded activity.</strong> Anonymous sessions are not identified people. Figures reflect only events received by the site.'}}
function render(){renderMode();renderKPIs();renderChart();renderPages();renderChannels();renderCampaigns();renderInbox();const updated=new Date(snapshot.updatedAt||Date.now());$('#last-updated').textContent=`Updated ${Number.isNaN(updated.getTime())?'just now':updated.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'America/Chicago'})} · Refreshes while this page is visible.`;$('#export-data').disabled=false}

const chart={left:53,right:876,top:16,bottom:236,width:900,height:280,max:1};
function renderChart(){const svg=$('#traffic-svg'),rows=snapshot.series;chart.width=Math.max(300,Math.round(svg.getBoundingClientRect().width)||900);chart.height=chart.width<600?230:280;chart.left=42;chart.right=chart.width-20;chart.top=18;chart.bottom=chart.height-42;svg.setAttribute('viewBox',`0 0 ${chart.width} ${chart.height}`);svg.style.aspectRatio=`${chart.width} / ${chart.height}`;chart.max=Math.max(1,...rows.flatMap(row=>[row.views,row.visitors]));const ceiling=Math.ceil(chart.max/4)*4;chart.max=Math.max(4,ceiling);const x=index=>chart.left+(rows.length<=1?.5:index/(rows.length-1))*(chart.right-chart.left);const y=value=>chart.bottom-value/chart.max*(chart.bottom-chart.top);let markup='<title id="traffic-svg-title">Portfolio traffic over time</title><desc id="traffic-svg-desc">Views and anonymous sessions for the selected period. Use left and right arrow keys to inspect dates. A data table is also available.</desc><defs><linearGradient id="traffic-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--dash-accent)" stop-opacity=".16"/><stop offset="1" stop-color="var(--dash-accent)" stop-opacity="0"/></linearGradient></defs>';
for(let i=0;i<=4;i++){const yy=chart.bottom-i/4*(chart.bottom-chart.top),value=chart.max*i/4;markup+=`<path d="M${chart.left} ${yy}H${chart.right}" stroke="var(--dash-rule)" stroke-width=".7" ${i?'stroke-dasharray="3 5"':''}/><text x="${chart.left-13}" y="${yy+3}" text-anchor="end" font-size="10" fill="var(--dash-muted)">${compact(value)}</text>`}
if(rows.length){const indices=[...new Set([0,Math.round((rows.length-1)*.25),Math.round((rows.length-1)*.5),Math.round((rows.length-1)*.75),rows.length-1])];for(const index of indices)markup+=`<text x="${x(index)}" y="${chart.height-14}" text-anchor="middle" font-size="10" fill="var(--dash-muted)">${escapeHTML(dateLabel(rows[index].date))}</text>`;const line=key=>rows.map((row,index)=>`${index?'L':'M'}${x(index).toFixed(2)} ${y(row[key]).toFixed(2)}`).join(' ');markup+=`<path d="${line('views')} L${x(rows.length-1)} ${chart.bottom} L${x(0)} ${chart.bottom} Z" fill="url(#traffic-fill)"/><path d="${line('visitors')}" fill="none" stroke="var(--theme-blue)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="${line('views')}" fill="none" stroke="var(--dash-accent)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;if(rows.length===1)markup+=`<circle cx="${x(0)}" cy="${y(rows[0].views)}" r="3" fill="var(--dash-accent)"/>`}
markup+='<g id="chart-focus" hidden><line id="chart-focus-line" stroke="var(--dash-muted)" stroke-dasharray="4 5" stroke-width="1"/><circle id="chart-focus-views" r="4" fill="var(--dash-accent)" stroke="var(--dash-bg)" stroke-width="2"/><circle id="chart-focus-visitors" r="4" fill="var(--theme-blue)" stroke="var(--dash-bg)" stroke-width="2"/></g>';svg.innerHTML=markup;$('#chart-empty').hidden=rows.some(row=>row.views||row.visitors);$('#chart-detail').textContent=rows.length?'Move across the chart, or use its arrow keys, to inspect a date.':'No recorded dates are available in this period.';chartIndex=-1;$('#chart-data-table').innerHTML=`<table class="dash-table dash-chart-data-table"><caption class="dash-sr">Traffic values by date</caption><thead><tr><th scope="col">Date</th><th scope="col">Views</th><th scope="col">Anonymous sessions</th></tr></thead><tbody>${rows.length?rows.map(row=>`<tr><td>${escapeHTML(dateLabel(row.date,true))}</td><td>${count(row.views)}</td><td>${count(row.visitors)}</td></tr>`).join(''):emptyTable(3,'No recorded dates in this period.')}</tbody></table>`}
function focusChart(index){const rows=snapshot?.series;if(!rows?.length)return;chartIndex=Math.max(0,Math.min(rows.length-1,index));const row=rows[chartIndex],x=chart.left+(rows.length<=1?.5:chartIndex/(rows.length-1))*(chart.right-chart.left),yv=chart.bottom-row.views/chart.max*(chart.bottom-chart.top),ys=chart.bottom-row.visitors/chart.max*(chart.bottom-chart.top),group=$('#chart-focus');if(!group)return;group.removeAttribute('hidden');const line=$('#chart-focus-line');line.setAttribute('x1',x);line.setAttribute('x2',x);line.setAttribute('y1',chart.top);line.setAttribute('y2',chart.bottom);for(const[id,y]of[['#chart-focus-views',yv],['#chart-focus-visitors',ys]]){$(id).setAttribute('cx',x);$(id).setAttribute('cy',y)}$('#chart-detail').textContent=`${dateLabel(row.date,true)} · ${count(row.views)} views · ${count(row.visitors)} anonymous sessions`}
listen($('#traffic-svg'),'pointermove',event=>{if(!snapshot?.series.length)return;const rect=event.currentTarget.getBoundingClientRect();if(!rect.width)return;const x=(event.clientX-rect.left)/rect.width*chart.width;focusChart(Math.round((x-chart.left)/(chart.right-chart.left)*(snapshot.series.length-1)))});
listen($('#traffic-svg'),'keydown',event=>{if(!snapshot?.series.length)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();focusChart(event.key==='Home'?0:event.key==='End'?snapshot.series.length-1:chartIndex<0?0:chartIndex+(event.key==='ArrowLeft'?-1:1))}});
listen(window,'resize',()=>{if(snapshot)renderChart()});
listen($('#chart-table-toggle'),'click',event=>{const open=event.currentTarget.getAttribute('aria-expanded')!=='true';event.currentTarget.setAttribute('aria-expanded',String(open));event.currentTarget.textContent=open?'Hide data table ↑':'View data table ↗';$('#chart-data-table').hidden=!open});

async function loadData({silent=false}={}){if(disposed)return;request?.abort();const sequence=++generation;request=new AbortController();const timeout=setTimeout(()=>request.abort(),18000);if(!silent){content.setAttribute('aria-busy','true');fetchState.dataset.error='false';fetchState.textContent=snapshot?'Refreshing the recorded signal…':'Connecting to the portfolio data…'}$('#refresh-data').disabled=true;
try{const response=await fetch(`/api/admin/overview?range=${encodeURIComponent(rangeSelect.value)}${demo?'&demo=1':''}`,{credentials:'same-origin',headers:{Accept:'application/json'},signal:request.signal,cache:'no-store'});if(sequence!==generation||disposed)return;if(response.status===401||response.status===403){snapshot=null;$('#access-required').hidden=false;content.hidden=true;$('#export-data').disabled=true;fetchState.textContent='An authenticated owner session is required.';$('#data-mode').textContent='OWNER SESSION REQUIRED';return}$('#access-required').hidden=true;content.hidden=false;if(!response.ok)throw new Error(response.status===503?'The analytics database is not available yet.':'The data connection could not be completed.');const payload=await response.json();if(sequence!==generation||disposed)return;if(!payload||typeof payload!=='object'||Array.isArray(payload)||!payload.totals)throw new Error('The data service returned an unexpected response.');snapshot=normalize(payload);$('#access-required').hidden=true;content.hidden=false;render();fetchState.dataset.error='false';fetchState.textContent=snapshot.mode==='demo'?'Synthetic demonstration data. Collected traffic is unchanged.':`Connected · ${rangeSelect.options[rangeSelect.selectedIndex].textContent.toLowerCase()} · recorded events only.`}
catch(error){if(sequence!==generation||disposed)return;if(error.name==='AbortError'){if(!silent)showError('The request took too long. Please try again.')}else showError(error.message||'The data connection could not be completed.')}
finally{clearTimeout(timeout);if(sequence===generation&&!disposed){$('#refresh-data').disabled=false;content.setAttribute('aria-busy','false')}}}
function showError(message){fetchState.dataset.error='true';fetchState.replaceChildren(document.createTextNode(`${message}${snapshot?' Showing the last confirmed result.':''} `));const retry=document.createElement('button');retry.type='button';retry.className='dash-text-button';retry.textContent='Retry ↻';retry.addEventListener('click',()=>loadData());fetchState.append(retry);if(!snapshot){$('#data-mode').textContent='CONNECTION UNAVAILABLE';$('#chart-empty').hidden=false;$('#chart-empty').innerHTML='A signal is waiting.<br><span>Connect the data service to see recorded activity.</span>'}}

function setTab(next,{updateURL=true}={}){if(!allowedTabs.includes(next))next='overview';tab=next;demoLink.href=`dashboard.html${demo?'':'?demo=1'}#${next}`;document.querySelectorAll('[data-dash-tab]').forEach(button=>{if(button.dataset.dashTab===next)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});document.querySelectorAll('.dash-panel-view').forEach(panel=>panel.hidden=panel.id!=='view-'+next);$('#breadcrumb-current').textContent=next.toUpperCase();if(updateURL)history.replaceState(null,'','#'+next);closeSidebar(false)}
document.querySelectorAll('[data-dash-tab]').forEach(button=>listen(button,'click',()=>setTab(button.dataset.dashTab)));document.querySelectorAll('[data-open-tab]').forEach(button=>listen(button,'click',()=>{setTab(button.dataset.openTab);$('#dashboard-main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'})}));listen(window,'hashchange',()=>setTab(location.hash.slice(1),{updateURL:false}));
listen(rangeSelect,'change',()=>loadData());listen($('#refresh-data'),'click',()=>loadData());listen($('#content-search'),'input',()=>{if(snapshot)renderPages()});listen($('#content-sort'),'change',()=>{if(snapshot)renderPages()});listen($('#inbox-filter'),'change',()=>{if(snapshot)renderInbox()});
listen($('#inbox-list'),'click',async event=>{const button=event.target.closest('[data-inquiry-id]');if(!button||!snapshot||demo)return;const id=button.dataset.inquiryId,status=button.dataset.inquiryStatus;if(pendingInquiries.has(id)||!['new','reviewed','archived'].includes(status))return;pendingInquiries.add(id);const card=button.closest('.dash-message');card?.querySelectorAll('button').forEach(node=>node.disabled=true);try{const response=await fetch(`/api/admin/inquiries/${encodeURIComponent(id)}`,{method:'PATCH',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({status})});if(!response.ok)throw new Error(response.status===401||response.status===403?'Your owner session is no longer available. Reload the protected dashboard.':'The message status could not be saved.');const row=snapshot.inquiries.find(item=>item.id===id);if(row)row.status=status;renderKPIs();toast(`Message marked ${status}. No reply was sent.`)}catch(error){toast(error.message);card?.querySelectorAll('button').forEach(node=>node.disabled=false)}finally{pendingInquiries.delete(id);if(snapshot){renderInbox();const replacement=[...$('#inbox-list').querySelectorAll('[data-inquiry-id]')].find(node=>node.dataset.inquiryId===id);(replacement||$('#inbox-filter')).focus({preventScroll:true})}}});

listen($('#campaign-builder'),'submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;let url;try{url=new URL($('#campaign-destination').value.trim());if(!['http:','https:'].includes(url.protocol))throw new Error()}catch{toast('Choose a complete http or https destination.');$('#campaign-destination').focus();return}for(const[field,key]of[['campaign-source','utm_source'],['campaign-medium','utm_medium'],['campaign-name','utm_campaign'],['campaign-variant','utm_content']]){const value=$('#'+field).value.trim();if(value)url.searchParams.set(key,value);else url.searchParams.delete(key)}$('#campaign-url').value=url.href;$('#campaign-output').hidden=false;$('#campaign-copy-status').textContent='Ready to copy. Building this link does not publish or send it.'});
listen($('#copy-campaign'),'click',async()=>{const field=$('#campaign-url');try{if(!navigator.clipboard?.writeText)throw new Error();await navigator.clipboard.writeText(field.value);$('#campaign-copy-status').textContent='Link copied. Share it wherever you choose.'}catch{field.focus();field.select();$('#campaign-copy-status').textContent='The link is selected. Use your device’s copy command.'}});
function csvCell(value){let text=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(text))text="'"+text;return'"'+text.replace(/"/g,'""')+'"'}
function csvRows(){if(tab==='content')return[['Page path','Views','Engaged'],...filteredPages().map(row=>[row.path,row.views,row.engaged])];if(tab==='campaigns')return[['Source','Medium','Campaign','Views','Conversions'],...snapshot.campaigns.map(row=>[row.source,row.medium,row.campaign,row.views,row.conversions])];if(tab==='inbox')return[['ID','Name','Email','Message','Created at','Status'],...filteredInquiries().map(row=>[row.id,row.name,row.email,row.message,row.createdAt,row.status])];return[['Workspace',snapshot.mode||'unknown'],['Range',rangeSelect.value],[],['Metric','Count'],...Object.entries(snapshot.totals).map(([key,value])=>[key,value]),[],['Date','Views','Anonymous sessions'],...snapshot.series.map(row=>[row.date,row.views,row.visitors])]}
listen($('#export-data'),'click',()=>{if(!snapshot)return;const csv='\uFEFF'+csvRows().map(row=>row.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download=`sub-${snapshot.mode||'data'}-${tab}-${rangeSelect.value}.csv`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${demo?'Demonstration':'Recorded'} ${tab} data exported.`)});

const sidebar=$('#dash-sidebar'),scrim=$('#sidebar-scrim'),menuButton=$('#sidebar-open');let previousFocus=null;
function openSidebar(){previousFocus=document.activeElement;sidebar.inert=false;sidebar.dataset.open='true';scrim.hidden=false;$('.dash-body').inert=true;document.body.dataset.drawerOpen='true';menuButton.setAttribute('aria-expanded','true');$('#sidebar-close').focus()}
function closeSidebar(restore=true){const open=sidebar.dataset.open==='true';sidebar.dataset.open='false';scrim.hidden=true;sidebar.inert=narrow.matches;$('.dash-body').inert=false;delete document.body.dataset.drawerOpen;menuButton.setAttribute('aria-expanded','false');if(open&&restore)previousFocus?.focus({preventScroll:true})}
listen(menuButton,'click',openSidebar);listen($('#sidebar-close'),'click',()=>closeSidebar());listen(scrim,'click',()=>closeSidebar());listen(document,'keydown',event=>{if(sidebar.dataset.open!=='true')return;if(event.key==='Escape'){event.preventDefault();closeSidebar()}else if(event.key==='Tab'){const buttons=[...sidebar.querySelectorAll('a,button')].filter(node=>node.getClientRects().length&&!node.disabled);const first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
const narrow=matchMedia('(max-width:760px)');listen(narrow,'change',()=>closeSidebar(false));sidebar.inert=narrow.matches;
const poll=setInterval(()=>{if(document.hidden||pendingInquiries.size||!snapshot)return;const focused=document.activeElement;if(focused?.matches('input,textarea,select')||$('#inbox-list').contains(focused))return;loadData({silent:true})},30000);cleanups.push(()=>clearInterval(poll));listen(document,'visibilitychange',()=>{if(!document.hidden&&snapshot)loadData({silent:true})});
function dispose(){if(disposed)return;disposed=true;generation++;request?.abort();clearTimeout(toastTimer);cleanups.splice(0).forEach(cleanup=>cleanup())}
listen(window,'pagehide',dispose,{once:true});listen(window,'pageshow',event=>{if(event.persisted)location.reload()});
setTab(tab,{updateURL:false});loadData();
